#include <iostream>
#include <mutex>
#include <thread>
#include <vector>

int main() {
    long long total = 0;
    std::mutex candado;
    std::vector<std::thread> hilos;

    for (int i = 0; i < 4; ++i) {
        hilos.emplace_back([&total, &candado, i]() {
            long long parcial = 0;
            for (int k = 1; k <= 1000; ++k) {
                parcial += i * 1000 + k;
            }
            std::lock_guard<std::mutex> bloqueo(candado);
            total += parcial;
        });
    }

    for (std::thread& h : hilos) {
        h.join();
    }

    std::cout << total << '\n'; // 8002000
    return 0;
}

#include <future>
#include <iostream>

long long sumar_hasta(int n) {
    long long total = 0;
    for (int i = 1; i <= n; ++i) {
        total += i;
    }
    return total;
}

int main() {
    std::future<long long> fut = std::async(std::launch::async, sumar_hasta, 1000);
    std::cout << "trabajando...\n";
    std::cout << fut.get() << '\n'; // 500500
    return 0;
}

