#include <cmath>
#include <iostream>
#include <stdexcept>

bool es_no_negativo(double x) noexcept {
    return x >= 0.0;
}

double raiz(double x) {
    if (!es_no_negativo(x)) {
        throw std::domain_error("no existe raiz real de un negativo");
    }
    return std::sqrt(x);
}

int main() {
    try {
        std::cout << raiz(16.0) << '\n'; // 4
        std::cout << raiz(-4.0) << '\n'; // no se imprime
    } catch (const std::exception& e) {
        std::cout << "error: " << e.what() << '\n';
    }
    return 0;
}

#include <iostream>
#include <mutex>
#include <thread>
#include <vector>

int main() {
    const int n = 1000000;
    const int partes = 4;
    const int bloque = n / partes;

    long long total = 0;
    std::mutex candado;
    std::vector<std::thread> hilos;

    for (int i = 0; i < partes; ++i) {
        const int inicio = i * bloque + 1;
        const int fin = (i == partes - 1) ? n : (i + 1) * bloque;

        hilos.emplace_back([inicio, fin, &total, &candado]() {
            long long parcial = 0;
            for (int k = inicio; k <= fin; ++k) {
                parcial += k;
            }
            std::lock_guard<std::mutex> bloqueo(candado);
            total += parcial;
        });
    }

    for (std::thread& h : hilos) {
        h.join();
    }

    std::cout << total << '\n'; // 500000500000
    return 0;
}

